# 8.5 Aplicació: càlcul de la distància a un punt inaccessible
# Apunts de la Unitat 8 de 4t ESO A (Semblança. Aplicacions). Cada resultat es comprova amb ck().
from comu import *
from fig8 import *

xs = sp.Symbol('x')
def solve1(eq): r = sp.solve(eq, xs); assert len(r) == 1, r; return r[0]

s5 = box('def', L('El problema', 'El problema', 'The problem'),
  P(r"Volem saber la distància del punt \(B\), on som, a un punt \(A\) on <strong>no podem arribar</strong>: un arbre a l'altra riba d'un riu, una illa, un vaixell, l'altre costat d'un barranc… No podem estendre una cinta mètrica fins a \(A\), però sí que podem <strong>mesurar a la nostra banda</strong>.",
    r"Queremos saber la distancia del punto \(B\), donde estamos, a un punto \(A\) al que <strong>no podemos llegar</strong>: un árbol en la otra orilla de un río, una isla, un barco, el otro lado de un barranco… No podemos extender una cinta métrica hasta \(A\), pero sí podemos <strong>medir en nuestro lado</strong>.",
    r"We want to know the distance from point \(B\), where we are, to a point \(A\) we <strong>can't reach</strong>: a tree on the far bank of a river, an island, a boat, the other side of a ravine… We can't stretch a tape measure to \(A\), but we <strong>can measure on our side</strong>.")
  + P(r"La idea és construir, amb estaques i mesures a la nostra riba, <strong>dos triangles semblants</strong> en què un dels costats siga la distància \(x=\overline{AB}\) que busquem. Després, la proporció entre costats homòlegs ens dona \(x\).",
      r"La idea es construir, con estacas y medidas en nuestra orilla, <strong>dos triángulos semejantes</strong> en los que uno de los lados sea la distancia \(x=\overline{AB}\) que buscamos. Después, la proporción entre lados homólogos nos da \(x\).",
      r"The idea is to build, with stakes and measurements on our bank, <strong>two similar triangles</strong> where one side is the distance \(x=\overline{AB}\) we're looking for. Then the proportion between corresponding sides gives us \(x\)."))

s5 += box('prop', L('Mètode 1: triangles en posició de Tales', 'Método 1: triángulos en posición de Tales', 'Method 1: triangles in Thales position'),
  ol(L(r"Des de \(B\) mirem cap a \(A\) i ens allunyem del riu en la mateixa direcció fins a un punt \(B'\). Mesurem \(d=\overline{BB'}\).", r"Desde \(B\) miramos hacia \(A\) y nos alejamos del río en la misma dirección hasta un punto \(B'\). Medimos \(d=\overline{BB'}\).", r"From \(B\) we look towards \(A\) and walk away from the river in the same direction to a point \(B'\). We measure \(d=\overline{BB'}\)."),
     L(r"En \(B\) i en \(B'\) tracem dues rectes <strong>perpendiculars</strong> a la recta \(AB\) (són paral·leles entre elles).", r"En \(B\) y en \(B'\) trazamos dos rectas <strong>perpendiculares</strong> a la recta \(AB\) (son paralelas entre sí).", r"At \(B\) and at \(B'\) we draw two lines <strong>perpendicular</strong> to line \(AB\) (they are parallel to each other)."),
     L(r"Clavem una estaca \(C\) en la primera perpendicular i mesurem \(a=\overline{BC}\). En la segona busquem el punt \(C'\) des del qual veiem \(C\) i \(A\) <strong>alineats</strong>, i mesurem \(b=\overline{B'C'}\).", r"Clavamos una estaca \(C\) en la primera perpendicular y medimos \(a=\overline{BC}\). En la segunda buscamos el punto \(C'\) desde el que vemos \(C\) y \(A\) <strong>alineados</strong>, y medimos \(b=\overline{B'C'}\).", r"We drive a stake \(C\) into the first perpendicular and measure \(a=\overline{BC}\). On the second we find the point \(C'\) from which \(C\) and \(A\) look <strong>lined up</strong>, and measure \(b=\overline{B'C'}\)."))
  + figs(G(inacc_tales(), W=230, pad=26))
  + P(r"Els triangles \(ABC\) i \(AB'C'\) tenen l'angle \(\hat A\) comú i \(BC\parallel B'C'\): estan en <strong>posició de Tales</strong> i són semblants. Com que \(\overline{AB'}=x+d\):",
      r"Los triángulos \(ABC\) y \(AB'C'\) tienen el ángulo \(\hat A\) común y \(BC\parallel B'C'\): están en <strong>posición de Tales</strong> y son semejantes. Como \(\overline{AB'}=x+d\):",
      r"Triangles \(ABC\) and \(AB'C'\) share angle \(\hat A\) and \(BC\parallel B'C'\): they are in <strong>Thales position</strong> and similar. Since \(\overline{AB'}=x+d\):")
  + D(r"\frac{x}{a}=\frac{x+d}{b}\ \Rightarrow\ bx=ax+ad\ \Rightarrow\ x=\frac{a\cdot d}{b-a}")
  + P(r"<strong>Exemple.</strong> Si \(d=10\) m, \(a=4\) m i \(b=5\) m:", r"<strong>Ejemplo.</strong> Si \(d=10\) m, \(a=4\) m y \(b=5\) m:", r"<strong>Example.</strong> If \(d=10\) m, \(a=4\) m and \(b=5\) m:")
  + D(r"\frac{x}{4}=\frac{x+10}{5}\ \Rightarrow\ 5x=4x+40\ \Rightarrow\ x=40\ \text{m}")
  + note(r"No cal memoritzar la fórmula: planteja la proporció i resol l'equació de primer grau. Compte a no confondre \(\overline{AB'}=x+d\) amb \(d\).",
         r"No hace falta memorizar la fórmula: plantea la proporción y resuelve la ecuación de primer grado. Cuidado con no confundir \(\overline{AB'}=x+d\) con \(d\).",
         r"No need to memorise the formula: set up the proportion and solve the linear equation. Be careful not to confuse \(\overline{AB'}=x+d\) with \(d\).", '⚠️'))
ck(solve1(xs / 4 - (xs + 10) / 5), 40); ck(R(4 * 10, 5 - 4), 40)

s5 += box('prop', L('Mètode 2: triangles oposats pel vèrtex', 'Método 2: triángulos opuestos por el vértice', 'Method 2: vertically opposite triangles'),
  ol(L(r"Des de \(B\), perpendicularment a \(AB\), caminem per la riba fins a \(C\) (hi clavem una estaca) i seguim fins a \(D\). Mesurem \(\overline{BC}\) i \(\overline{CD}\).", r"Desde \(B\), perpendicularmente a \(AB\), caminamos por la orilla hasta \(C\) (clavamos una estaca) y seguimos hasta \(D\). Medimos \(\overline{BC}\) y \(\overline{CD}\).", r"From \(B\), perpendicular to \(AB\), we walk along the bank to \(C\) (we drive in a stake) and carry on to \(D\). We measure \(\overline{BC}\) and \(\overline{CD}\)."),
     L(r"Des de \(D\) ens allunyem del riu perpendicularment fins al punt \(E\) des del qual veiem \(C\) i \(A\) alineats. Mesurem \(\overline{DE}\).", r"Desde \(D\) nos alejamos del río perpendicularmente hasta el punto \(E\) desde el que vemos \(C\) y \(A\) alineados. Medimos \(\overline{DE}\).", r"From \(D\) we walk away from the river at right angles until the point \(E\) from which \(C\) and \(A\) look lined up. We measure \(\overline{DE}\)."))
  + figs(G(inacc_cross(('x', '15 m', '3', '4 m')), W=230, pad=26))
  + P(r"Els triangles \(ABC\) i \(EDC\) són rectangles i tenen els angles en \(C\) iguals (oposats pel vèrtex): són semblants. Els costats homòlegs són \(AB\leftrightarrow ED\) i \(BC\leftrightarrow DC\):",
      r"Los triángulos \(ABC\) y \(EDC\) son rectángulos y tienen los ángulos en \(C\) iguales (opuestos por el vértice): son semejantes. Los lados homólogos son \(AB\leftrightarrow ED\) y \(BC\leftrightarrow DC\):",
      r"Triangles \(ABC\) and \(EDC\) are right triangles with equal angles at \(C\) (vertically opposite): they're similar. Corresponding sides are \(AB\leftrightarrow ED\) and \(BC\leftrightarrow DC\):")
  + D(r"\frac{x}{\overline{DE}}=\frac{\overline{BC}}{\overline{CD}}\ \Rightarrow\ \frac{x}{4}=\frac{15}{3}\ \Rightarrow\ x=\frac{4\cdot15}{3}=20\ \text{m}")
  + widget('w-inacc', '🌊', L("Calcula l'amplària del riu", 'Calcula la anchura del río', "Find the river's width"),
           [seg([('T', L('Mètode 1 (Tales)', 'Método 1 (Tales)', 'Method 1 (Thales)')), ('X', L('Mètode 2 (oposats)', 'Método 2 (opuestos)', 'Method 2 (opposite)'))]),
            '<div class="wrow">' + rng('d', 2, 30, 1, 10, 'd') + rng('a', 1, 10, 0.5, 4, 'a') + rng('b', 1.5, 15, 0.5, 5, 'b') + '</div>',
            '<div class="wrow">' + rng('p', 2, 40, 1, 15, 'BC') + rng('q', 1, 10, 0.5, 3, 'CD') + rng('r', 1, 10, 0.5, 4, 'DE') + '</div>'])
  + drill('inacc', 'Entrena: distàncies inaccessibles', 'Entrena: distancias inaccesibles', 'Train: inaccessible distances'))
ck(R(4 * 15, 3), 20)

s5 += levels(
 [prob(L(r"Per a saber l'amplària d'un riu fem servir el mètode 2 i mesurem \(\overline{BC}=12\) m, \(\overline{CD}=4\) m i \(\overline{DE}=5\) m. Quant fa d'ample el riu?", r"Para saber la anchura de un río usamos el método 2 y medimos \(\overline{BC}=12\) m, \(\overline{CD}=4\) m y \(\overline{DE}=5\) m. ¿Cuánto mide de ancho el río?", r"To find a river's width we use method 2 and measure \(\overline{BC}=12\) m, \(\overline{CD}=4\) m and \(\overline{DE}=5\) m. How wide is the river?"),
       D(r"\frac{x}{5}=\frac{12}{4}\ \Rightarrow\ x=\frac{5\cdot12}{4}=\boxed{15\ \text{m}}")),
  prob(L(r"Amb el mètode 1 hem mesurat \(d=\overline{BB'}=6\) m, \(a=\overline{BC}=3\) m i \(b=\overline{B'C'}=3{,}6\) m. Calcula la distància \(x=\overline{AB}\).", r"Con el método 1 hemos medido \(d=\overline{BB'}=6\) m, \(a=\overline{BC}=3\) m y \(b=\overline{B'C'}=3{,}6\) m. Calcula la distancia \(x=\overline{AB}\).", r"Using method 1 we measured \(d=\overline{BB'}=6\) m, \(a=\overline{BC}=3\) m and \(b=\overline{B'C'}=3.6\) m. Find the distance \(x=\overline{AB}\)."),
       D(r"\frac{x}{3}=\frac{x+6}{3{,}6}\ \Rightarrow\ 3{,}6x=3x+18\ \Rightarrow\ 0{,}6x=18\ \Rightarrow\ x=\boxed{30\ \text{m}}"))],
 [prob(L(r"Des de la platja volem saber a quina distància està un vaixell ancorat \(A\). Fem servir el mètode 1 amb \(d=20\) m, \(a=8\) m i \(b=8{,}5\) m. A quina distància del punt \(B\) està el vaixell?", r"Desde la playa queremos saber a qué distancia está un barco anclado \(A\). Usamos el método 1 con \(d=20\) m, \(a=8\) m y \(b=8{,}5\) m. ¿A qué distancia del punto \(B\) está el barco?", r"From the beach we want to know how far away an anchored boat \(A\) is. We use method 1 with \(d=20\) m, \(a=8\) m and \(b=8.5\) m. How far is the boat from point \(B\)?"),
       D(r"\frac{x}{8}=\frac{x+20}{8{,}5}\ \Rightarrow\ 8{,}5x=8x+160\ \Rightarrow\ 0{,}5x=160\ \Rightarrow\ x=\boxed{320\ \text{m}}"),
       P(r"Fixa't que una diferència menuda entre \(a\) i \(b\) dona una distància gran: cal mesurar amb molta cura.", r"Fíjate en que una diferencia pequeña entre \(a\) y \(b\) da una distancia grande: hay que medir con mucho cuidado.", r"Notice that a small difference between \(a\) and \(b\) gives a large distance: you have to measure very carefully.")),
  prob(L(r"Per a construir una passarel·la sobre un barranc, uns operaris fan servir el mètode 2: \(\overline{BC}=25\) m, \(\overline{CD}=4\) m i \(\overline{DE}=3{,}2\) m. Quina longitud ha de tindre la passarel·la?", r"Para construir una pasarela sobre un barranco, unos operarios usan el método 2: \(\overline{BC}=25\) m, \(\overline{CD}=4\) m y \(\overline{DE}=3{,}2\) m. ¿Qué longitud debe tener la pasarela?", r"To build a footbridge over a ravine, some workers use method 2: \(\overline{BC}=25\) m, \(\overline{CD}=4\) m and \(\overline{DE}=3.2\) m. How long must the footbridge be?"),
       D(r"\frac{x}{3{,}2}=\frac{25}{4}\ \Rightarrow\ x=\frac{3{,}2\cdot25}{4}=\boxed{20\ \text{m}}"))],
 [prob(L(r"Amb el mètode 1 (\(d=10\) m, \(a=4\) m, \(b=5\) m) hem trobat que l'arbre \(A\) està a \(x=40\) m de \(B\). Una amiga està en l'estaca \(C\). A quina distància està ella de l'arbre?", r"Con el método 1 (\(d=10\) m, \(a=4\) m, \(b=5\) m) hemos encontrado que el árbol \(A\) está a \(x=40\) m de \(B\). Una amiga está en la estaca \(C\). ¿A qué distancia está ella del árbol?", r"With method 1 (\(d=10\) m, \(a=4\) m, \(b=5\) m) we found that tree \(A\) is \(x=40\) m from \(B\). A friend is standing at stake \(C\). How far is she from the tree?"),
       P(r"El triangle \(ABC\) és rectangle en \(B\), amb catets \(\overline{AB}=40\) i \(\overline{BC}=4\). Apliquem el teorema de Pitàgores:", r"El triángulo \(ABC\) es rectángulo en \(B\), con catetos \(\overline{AB}=40\) y \(\overline{BC}=4\). Aplicamos el teorema de Pitágoras:", r"Triangle \(ABC\) has a right angle at \(B\), with legs \(\overline{AB}=40\) and \(\overline{BC}=4\). We apply Pythagoras' theorem:"),
       D(r"\overline{AC}=\sqrt{40^2+4^2}=\sqrt{1616}\approx\boxed{40{,}20\ \text{m}}"),
       P(r"I des de \(C'\): \(\overline{AC'}=\sqrt{50^2+5^2}=\sqrt{2525}\approx50{,}25\) m. Comprova que \(\frac{50{,}25}{40{,}20}\approx1{,}25=\frac54\), la raó de semblança.", r"Y desde \(C'\): \(\overline{AC'}=\sqrt{50^2+5^2}=\sqrt{2525}\approx50{,}25\) m. Comprueba que \(\frac{50{,}25}{40{,}20}\approx1{,}25=\frac54\), la razón de semejanza.", r"And from \(C'\): \(\overline{AC'}=\sqrt{50^2+5^2}=\sqrt{2525}\approx50.25\) m. Check that \(\frac{50.25}{40.20}\approx1.25=\frac54\), the scale factor."))])
ck(R(5 * 12, 4), 15); ck(solve1(xs / 3 - (xs + 6) / R(36, 10)), 30); ck(solve1(xs / 8 - (xs + 20) / R(85, 10)), 320); ck(R(32, 10) * 25 / 4, 20)
ck(S(40 ** 2 + 4 ** 2), 40.20, 2); ck(S(50 ** 2 + 5 ** 2), 50.25, 2); ck(S(2525) / S(1616), 1.25, 2)

s5 += practice([
  ('★', L(r"a) Amb el mètode 2 mesurem \(\overline{BC}=18\) m, \(\overline{CD}=3\) m i \(\overline{DE}=2{,}5\) m. Quant fa d'ample el riu? b) Amb el mètode 1 mesurem \(d=8\) m, \(a=2\) m i \(b=2{,}4\) m. Calcula \(\overline{AB}\).", r"a) Con el método 2 medimos \(\overline{BC}=18\) m, \(\overline{CD}=3\) m y \(\overline{DE}=2{,}5\) m. ¿Cuánto mide de ancho el río? b) Con el método 1 medimos \(d=8\) m, \(a=2\) m y \(b=2{,}4\) m. Calcula \(\overline{AB}\).", r"a) With method 2 we measure \(\overline{BC}=18\) m, \(\overline{CD}=3\) m and \(\overline{DE}=2.5\) m. How wide is the river? b) With method 1 we measure \(d=8\) m, \(a=2\) m and \(b=2.4\) m. Find \(\overline{AB}\).")),
  ('★★', L(r"c) Un riu fa 30 m d'ample. Amb el mètode 2 prenem \(\overline{BC}=12\) m i \(\overline{CD}=2\) m. Quant farà \(\overline{DE}\)?", r"c) Un río mide 30 m de ancho. Con el método 2 tomamos \(\overline{BC}=12\) m y \(\overline{CD}=2\) m. ¿Cuánto medirá \(\overline{DE}\)?", r"c) A river is 30 m wide. With method 2 we take \(\overline{BC}=12\) m and \(\overline{CD}=2\) m. How long will \(\overline{DE}\) be?")),
  ('★★★', L(r"d) Una illa està a 50 m de \(B\). Si fem el mètode 1 amb \(a=5\) m i \(d=10\) m, quant ha de mesurar \(b\)?", r"d) Una isla está a 50 m de \(B\). Si hacemos el método 1 con \(a=5\) m y \(d=10\) m, ¿cuánto debe medir \(b\)?", r"d) An island is 50 m from \(B\). If we use method 1 with \(a=5\) m and \(d=10\) m, how long must \(b\) be?"))],
  P(r"a) \(\frac{x}{2{,}5}=\frac{18}{3}\Rightarrow x=15\) m. b) \(2{,}4x=2x+16\Rightarrow x=40\) m. c) \(\frac{30}{\overline{DE}}=\frac{12}{2}\Rightarrow\overline{DE}=5\) m. d) \(\frac{50}{5}=\frac{60}{b}\Rightarrow b=6\) m.",
    r"a) \(\frac{x}{2{,}5}=\frac{18}{3}\Rightarrow x=15\) m. b) \(2{,}4x=2x+16\Rightarrow x=40\) m. c) \(\frac{30}{\overline{DE}}=\frac{12}{2}\Rightarrow\overline{DE}=5\) m. d) \(\frac{50}{5}=\frac{60}{b}\Rightarrow b=6\) m.",
    r"a) \(\frac{x}{2.5}=\frac{18}{3}\Rightarrow x=15\) m. b) \(2.4x=2x+16\Rightarrow x=40\) m. c) \(\frac{30}{\overline{DE}}=\frac{12}{2}\Rightarrow\overline{DE}=5\) m. d) \(\frac{50}{5}=\frac{60}{b}\Rightarrow b=6\) m."))
ck(R(25, 10) * 18 / 3, 15); ck(solve1(xs / 2 - (xs + 8) / R(24, 10)), 40); ck(R(30 * 2, 12), 5); ck(R(60 * 5, 50), 6)
